class Solution:
    def correctBinaryTree(self, root: 'TreeNode') -> 'TreeNode':
        level = [root]
        parent = {root: None}
        while level:
            seen = set()
            # Scan the level from right to left: a bad node's right child was already seen
            for node in reversed(level):
                if node.right and node.right in seen:
                    par = parent[node]
                    # Remove reference from parent
                    if par.left is node:
                        par.left = None
                    else:
                        par.right = None
                    return root
                seen.add(node)
            nxt = []
            for node in level:
                if node.left:
                    parent[node.left] = node
                    nxt.append(node.left)
                if node.right:
                    parent[node.right] = node
                    nxt.append(node.right)
            level = nxt
        return root
